-- Lot 204 : payloads 91 a 120 sur 150.
--
-- Un texte propre a chaque IA. Les commandes etant neuves, aucune version
-- courante n'existe : rien n'est retire, tout est pose.

drop table if exists lot_extension_payloads;
create temporary table lot_extension_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-411","moteur":"chatgpt","payload":"[RaccourcIA — /longexposuretrail]\n\nMISSION\nGardez le sujet net tandis que personnes, lumières ou véhicules deviennent des traînées de mouvement. Simuler une pose longue cohérente avec le mouvement : sujet verrouillé, trajectoires continues et lumière physiquement plausible.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque pièce jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Si une information indispensable manque, pose UNE seule question à la fois, dans cet ordre conditionnel : Quels éléments doivent rester nets et lesquels doivent devenir des traînées ?. Après chaque réponse, réanalyse et produis dès que possible. Accepte « Choisis pour moi » pour toute préférence non critique.\n\nEXÉCUTION\nSimuler une pose longue cohérente avec le mouvement : sujet verrouillé, trajectoires continues et lumière physiquement plausible. Format par défaut : 4:5, haute définition. Si plusieurs images sont demandées, maintiens une continuité stricte entre elles. Si du texte exact est fourni, reproduis-le fidèlement; si le texte n’est pas indispensable, préfère une sortie sans texte.\n\nPRÉSERVER\nSujet principal, architecture, point de vue et sources lumineuses.\n\nÉVITER\nSujet fantôme involontaire, traînées sans origine, véhicules fusionnés, lumière incohérente. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nProduis l’image finale, pas un tutoriel. Vérifie silencieusement sujet, identité ou géométrie, proportions, perspective, lumière, ombres, matières, texte, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique clairement que l’image n’a pas été générée.","sha256":"f0397041689ca3d8f46b9661841295a02efb98348b87c7c9df101a764abdd272"},{"ref":"RCI-IMG-411","moteur":"claude","payload":"[RaccourcIA — /longexposuretrail]\n\nMISSION\nGardez le sujet net tandis que personnes, lumières ou véhicules deviennent des traînées de mouvement. Simuler une pose longue cohérente avec le mouvement : sujet verrouillé, trajectoires continues et lumière physiquement plausible.\n\nDÉCISION\nExamine d’abord toutes les images et documents, puis consolide les contraintes sans longue reformulation. Vérifie les capacités réellement disponibles avant de produire. Si le contexte suffit, exécute directement. Ne questionne jamais sur une information visible ou déjà fournie. Si un choix bloquant reste inconnu, pose UNE seule question à la fois : Quels éléments doivent rester nets et lesquels doivent devenir des traînées ?. Réévalue après chaque réponse; « Choisis pour moi » autorise une décision professionnelle sur les préférences secondaires.\n\nEXÉCUTION\nSimuler une pose longue cohérente avec le mouvement : sujet verrouillé, trajectoires continues et lumière physiquement plausible. Format par défaut : 4:5, haute définition. Si plusieurs images sont demandées, maintiens une continuité stricte entre elles. Si du texte exact est fourni, reproduis-le fidèlement; si le texte n’est pas indispensable, préfère une sortie sans texte.\n\nPRÉSERVER\nSujet principal, architecture, point de vue et sources lumineuses.\n\nÉVITER\nSujet fantôme involontaire, traînées sans origine, véhicules fusionnés, lumière incohérente. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nProduis l’image finale, pas un tutoriel. Vérifie silencieusement sujet, identité ou géométrie, proportions, perspective, lumière, ombres, matières, texte, recadrage et artefacts; corrige ce qui peut l’être. Sans moteur image connecté, livre un brief de transfert autonome, précis et directement exploitable; ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"39db74e6823f5874f2d2374acae5f6869c2cbb6a27ef47ef07150b9afd64445c"},{"ref":"RCI-IMG-411","moteur":"gemini","payload":"[RaccourcIA — /longexposuretrail]\n\nMISSION\nGardez le sujet net tandis que personnes, lumières ou véhicules deviennent des traînées de mouvement. Simuler une pose longue cohérente avec le mouvement : sujet verrouillé, trajectoires continues et lumière physiquement plausible.\n\nDÉCISION\nInspecte visuellement toutes les références avant le texte de contexte et attribue à chacune son rôle : sujet, style, données ou composition. Si les éléments indispensables sont présents, génère immédiatement. Ne redemande jamais ce qui est visible ou déjà connu. Si une décision critique manque, pose UNE seule question à la fois : Quels éléments doivent rester nets et lesquels doivent devenir des traînées ?. Après la réponse, exécute dès que le contexte devient suffisant; « Choisis pour moi » permet de décider les préférences créatives secondaires.\n\nEXÉCUTION\nSimuler une pose longue cohérente avec le mouvement : sujet verrouillé, trajectoires continues et lumière physiquement plausible. Format par défaut : 4:5, haute définition. Si plusieurs images sont demandées, maintiens une continuité stricte entre elles. Si du texte exact est fourni, reproduis-le fidèlement; si le texte n’est pas indispensable, préfère une sortie sans texte.\n\nPRÉSERVER\nSujet principal, architecture, point de vue et sources lumineuses.\n\nÉVITER\nSujet fantôme involontaire, traînées sans origine, véhicules fusionnés, lumière incohérente. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nProduis l’image finale, pas un tutoriel. Vérifie silencieusement sujet, identité ou géométrie, proportions, perspective, lumière, ombres, matières, texte, recadrage et artefacts; corrige ce qui peut l’être. Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"484f08605f7f860516cab1beb85c1859af2b32bf023a43e1b2909e0387087ee6"},{"ref":"RCI-IMG-412","moteur":"chatgpt","payload":"[RaccourcIA — /halftonepress]\n\nMISSION\nTransformez une image en impression demi-teinte avec trame, encre et papier crédibles. Construire une vraie logique de trame demi-teinte, léger désalignement d’encre, texture de papier et contraste d’impression.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque pièce jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Si une information indispensable manque, pose UNE seule question à la fois, dans cet ordre conditionnel : Souhaitez-vous une trame noir et blanc, bichromie ou couleur limitée ?. Après chaque réponse, réanalyse et produis dès que possible. Accepte « Choisis pour moi » pour toute préférence non critique.\n\nEXÉCUTION\nConstruire une vraie logique de trame demi-teinte, léger désalignement d’encre, texture de papier et contraste d’impression. Format par défaut : 4:5, haute définition. Si plusieurs images sont demandées, maintiens une continuité stricte entre elles. Si du texte exact est fourni, reproduis-le fidèlement; si le texte n’est pas indispensable, préfère une sortie sans texte.\n\nPRÉSERVER\nSilhouette, visage, zones de contraste, texte exact s’il existe.\n\nÉVITER\nMotifs moirés illisibles, texte détruit, saturation numérique uniforme, visage méconnaissable. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nProduis l’image finale, pas un tutoriel. Vérifie silencieusement sujet, identité ou géométrie, proportions, perspective, lumière, ombres, matières, texte, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique clairement que l’image n’a pas été générée.","sha256":"b494c543b4a96055deebef6b1937a9fe972dfc287d0f3fae382cb0bd793a7fc9"},{"ref":"RCI-IMG-412","moteur":"claude","payload":"[RaccourcIA — /halftonepress]\n\nMISSION\nTransformez une image en impression demi-teinte avec trame, encre et papier crédibles. Construire une vraie logique de trame demi-teinte, léger désalignement d’encre, texture de papier et contraste d’impression.\n\nDÉCISION\nExamine d’abord toutes les images et documents, puis consolide les contraintes sans longue reformulation. Vérifie les capacités réellement disponibles avant de produire. Si le contexte suffit, exécute directement. Ne questionne jamais sur une information visible ou déjà fournie. Si un choix bloquant reste inconnu, pose UNE seule question à la fois : Souhaitez-vous une trame noir et blanc, bichromie ou couleur limitée ?. Réévalue après chaque réponse; « Choisis pour moi » autorise une décision professionnelle sur les préférences secondaires.\n\nEXÉCUTION\nConstruire une vraie logique de trame demi-teinte, léger désalignement d’encre, texture de papier et contraste d’impression. Format par défaut : 4:5, haute définition. Si plusieurs images sont demandées, maintiens une continuité stricte entre elles. Si du texte exact est fourni, reproduis-le fidèlement; si le texte n’est pas indispensable, préfère une sortie sans texte.\n\nPRÉSERVER\nSilhouette, visage, zones de contraste, texte exact s’il existe.\n\nÉVITER\nMotifs moirés illisibles, texte détruit, saturation numérique uniforme, visage méconnaissable. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nProduis l’image finale, pas un tutoriel. Vérifie silenci